// Strips bare @layer ordering declarations (e.g. "@layer theme, base, utilities;")
// generated by Tailwind v4. Next.js webpack's css-loader parser rejects these.
// Named @layer blocks (@layer name { ... }) are preserved — only bodyless ones removed.
module.exports = (opts = {}) => ({
  postcssPlugin: "postcss-layer-fix",
  AtRule: {
    layer: (node) => {
      if (!node.nodes) node.remove();
    },
  },
});
module.exports.postcss = true;
